s.$t(\"alert.update\")\n                        )\n                    ) {\n                        let self = this;\n                        if (self.loading) {\n                            return;\n                        }\n                        self.loading = true;\n                        let data = { ...item, goods_id: self.goodsId };\n                        let index = self.items.findIndex(obj => {\n                            return obj.id === item.id;\n                        });\n                        this.$store\n                            .dispatch(\"goods/item/update\", data)\n                            .then(response => {\n                                self.loading = false;\n                                self.fetch();\n                            })\n                            .catch(error => {\n                                self.loading = false;\n                            });\n                    }\n                    break;\n                case \"AddShipping\":\n                    await this.$refs.shippingDialog.open(\n                        this.$t(\"alert.shipping\"),\n                        null,\n                        item\n                    );\n                    break;\n                case \"Delete\":\n                    if (\n                        await this.$refs.dialog.open(\n                            this.$t(\"button.confirm\"),\n                            this.$t(\"alert.delete\")\n                        )\n                    ) {\n                        let self = this;\n                        if (self.loading) {\n                            return;\n                        }\n                        if (item.updated === false) {\n                            let tempItems = self.items.filter(obj => {\n                                if (obj.id) {\n                                    return obj.id !== item.id;\n                                }\n                                return true;\n             